; ---- arrays ----
source:         db      'the quick brown fox jumps over the lazy dog and keeps on running', 10,        ; u8[126] const
                db      'short', 10, 'another line that is comfortably longer than one chunk',
                db      10
buf:            times 80 db 0        ; u8[80]
runSrc:         db      'ab', 10        ; u8[3] const
putNumber__digits: times 5 db 0        ; u8[5]

; ============================================================ heap ====
; No storage is emitted - a .COM owns everything past its image, so
; these are addresses and NASM does the arithmetic.

_hstack:        equ     270        ; 14 worst-case + 256 interrupt reserve
_htop:          equ     0FFFEh - _hstack

_hsize:         dw      _htop - _heap        ; NASM computes this
        align   2                           ; keep the u16 view aligned
_heap:
_heapw:         equ     _heap        ; same bytes, u16 view

; =========================================================== views ====
; No storage: each is a name for an offset into something else.

motext__logOp:  equ     _heap        ; u8[2048]
motext__logLine: equ     _heap + 2048        ; u16[2048]
motext__logCol: equ     _heap + 6144        ; u16[2048]
motext__logCh:  equ     _heap + 10240        ; u8[2048]
motext__logJoin: equ     _heap + 12288        ; bool[2048]
